import{_ as t}from"./chunks/tutorials-projektkurse-schueler-abitur.DLLe3ZGb.js";import{_ as a,o as s,c as u,a3 as r,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const o="/bilder/schueler/tutorials-projektkurse-einstellungen-fachbezogene-bemerkungen.png",l="/bilder/schueler/tutorials-projektkurse-fach.png",h="/bilder/schueler/tutorials-projektkurse-kurs.png",d="/bilder/schueler/tutorials-projektkurse-schueler-kurs.png",c="/bilder/schueler/tutorials-projektkurse-schueler-thema.png",w=JSON.parse('{"title":"Projektkurse, Facharbeiten und ihre Themen erfassen","description":"","frontmatter":{"title":"Projektkurse, Facharbeiten und ihre Themen erfassen","source_pageid":1303,"source_revision":4850},"headers":[],"relativePath":"schild3/schueler/thema-von-projektkurs-und-facharbeit-erfassen-tutorial.md","filePath":"schild3/schueler/thema-von-projektkurs-und-facharbeit-erfassen-tutorial.md"}'),g={name:"schild3/schueler/thema-von-projektkurs-und-facharbeit-erfassen-tutorial.md"};function k(m,i,p,b,f,j){return s(),u("div",null,[...i[0]||(i[0]=[r('<h1 id="projektkurse-facharbeiten-und-ihre-themen-erfassen" tabindex="-1">Projektkurse, Facharbeiten und ihre Themen erfassen <a class="header-anchor" href="#projektkurse-facharbeiten-und-ihre-themen-erfassen" aria-label="Permalink to &quot;Projektkurse, Facharbeiten und ihre Themen erfassen&quot;">​</a></h1><p><strong>Geltungsbereich:</strong> Das Beispiel zeigt einen Projektkurs in beiden Halbjahren der <strong>Q1</strong> nach der bisherigen APO-GOSt. <a href="https://bass.schule.nrw/9607.htm" target="_blank" rel="noreferrer">§ 11 Absatz 8</a> sieht zwei aufeinanderfolgende Halbjahre der Qualifikationsphase vor; der Kurs ist nicht generell auf Q1 beschränkt. Die neue Ordnung für die Kohorte ab EF 2027/28 ist getrennt zu behandeln; siehe <a href="/zeugnisse/pruefungsordnungen.html">Prüfungsordnungen zuordnen</a>.</p><p>Bereiten Sie Fach und Kurs vor und aktivieren Sie das fachbezogene Bemerkungsfeld. Anschließend können Sie Themen und Noten von Projektkurs- oder Facharbeiten dokumentieren.</p><h2 id="fachbezogene-bemerkungen-aktivieren" tabindex="-1">Fachbezogene Bemerkungen aktivieren <a class="header-anchor" href="#fachbezogene-bemerkungen-aktivieren" aria-label="Permalink to &quot;Fachbezogene Bemerkungen aktivieren&quot;">​</a></h2><p><a href="/bilder/schueler/tutorials-projektkurse-einstellungen-fachbezogene-bemerkungen.png"><img src="'+o+'" alt="Aktivieren Sie die Fachbezogenen Bemerkungen." loading="lazy"></a></p><p><em>Aktivieren Sie die Fachbezogenen Bemerkungen.</em></p><p>Damit das Thema der Projektkursarbeit in den Leistungsdaten in einem Kurs erfasst werden kann, muss in SchILD-NRW die Spalte mit den <em>Fachbezogenen Bemerkungen</em> angezeigt werden.</p><p>Dieses lässt sich über <em>Verwaltung ➜ Einstellungen ➜ Globale Einstellungen</em> mit einem Haken bei <strong>Fachbezogenes Bemerkungsfeld zeigen</strong> aktivieren.</p><h2 id="projektkurse-vorbereiten" tabindex="-1">Projektkurse vorbereiten <a class="header-anchor" href="#projektkurse-vorbereiten" aria-label="Permalink to &quot;Projektkurse vorbereiten&quot;">​</a></h2><h3 id="ein-unterrichtsfach-anlegen" tabindex="-1">Ein Unterrichtsfach anlegen <a class="header-anchor" href="#ein-unterrichtsfach-anlegen" aria-label="Permalink to &quot;Ein Unterrichtsfach anlegen&quot;">​</a></h3><p><a href="/bilder/schueler/tutorials-projektkurse-fach.png"><img src="'+l+'" alt="Legen Sie ein Fach an, das den Projektkursen zugeordnet werden kann." loading="lazy"></a></p><p><em>Legen Sie ein Fach an, das den Projektkursen zugeordnet werden kann.</em></p><p>Für einen Projektkurs muss ein übergeordnetes <em>Fach</em> unter <em>Kataloge ➜ Unterrichtsfächer</em> angelegt werden.</p><p>Beginnen Sie das <strong>Interne Kürzel</strong> beispielsweise mit <strong>PX</strong> für Projektkurs. Ein Projektkurs in Biologie kann <strong>PXB</strong> heißen. Für einen Projektkurs mit den beiden Leitfächern Biologie und Chemie bietet sich <strong>PXBC</strong> an.</p><p>Setzen Sie als <strong>ASD-Kürzel</strong> den Eintrag <em>PX</em>.</p><p>Vergeben Sie die Bezeichnung wie üblich und befüllen Sie die anderen Felder ebenso nach den Vorgaben beziehungsweise die frei wählbaren Felder wie gewünscht.</p><p>Als <strong>Bereich auf dem Zeugnis</strong> ist <em>Projektkurs</em> zu wählen. Ordnen Sie das <strong>Aufgabenfeld</strong> passend zu.</p><p>Unter <strong>Sonstige Einstellungen</strong> sind die Haken bei <strong>Fach der Oberstufe</strong> und <strong>Bei &quot;abgeschlossene Fächer holen&quot; berücksichtigen</strong> anzuwählen, wenn der Projektkurs wie im Beispiel vor dem Abschlussabschnitt endet.</p><p>Achten Sie auch daran, dass das Fach bei <em>auf Zeugnis</em> und <em>Sichtbar</em> angehakt ist.</p><h3 id="den-kurs-anlegen" tabindex="-1">Den Kurs anlegen <a class="header-anchor" href="#den-kurs-anlegen" aria-label="Permalink to &quot;Den Kurs anlegen&quot;">​</a></h3><p><a href="/bilder/schueler/tutorials-projektkurse-kurs.png"><img src="'+h+'" alt="Konfigureren Sie den Projektkurs für beide Halbjahre der Q1." loading="lazy"></a></p><p><em>Konfigureren Sie den Projektkurs für beide Halbjahre der Q1.</em></p><p>Der Kurs ist über <em>Kataloge ➜ Kurse</em> anzulegen.</p><p>Klicken Sie auf das <strong>+</strong>.<br> Achten Sie darauf, den Kurs für das richtige Halbjahr anzulegen (Q1, 1. beziehungsweise 2. Halbjahr).</p><p>Die Kursbezeichnung ist frei zu vergeben, hier wird <em>BI-PX1</em> gewählt. Legen Sie einen Projektkurs mit zwei Leitfächern an, könnte der Kurs <em>BiC-PX</em> oder <em>BC-PX1</em> genannt werden.</p><p>Als <strong>Fach</strong> ist das eben angelegte Fach zu wählen, hier im Beispiel <em>PXB</em>. Als <strong>alg. Kursart</strong> wird <em>PJK</em> gewählt. Wie Projektkurse aktuell anzulegen sind, ist den Schlüsseltabellen für die Statistik zu entnehmen, die an Ihrer Schule hierfür verantwortlich Person kann im Zweifelsfall helfen.</p><p>Tragen Sie die gewünschte <strong>Zeugnisbezeichnung</strong> ein.</p><p>Legen Sie die übrigen Daten entsprechend der anderen Oberstufenkurse an. Achten Sie auf die <strong>Schienen</strong>.</p><p>Wählen Sie die bei Ihnen für Kurse der Oberstufe verwendete <strong>Kursart</strong>. Legen Sie den Kurs in den tatsächlich vorgesehenen Halbjahren an; im Beispiel sind dies Q1.1 und Q1.2.</p><p>Bei Bedarf: Sie können den Kurs ganz links markieren, mit der rechten Maustaste ein Kontextmenü aufrufen, um den Kurs zu kopieren. Nun kann er in einem anderen Halbjahr, üblicherweise Q1, 2. Halbjahr, eingefügt werden.</p>',30),e("div",{"data-hint-kind":"right",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"right","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"m8 12 3 3 5-6"})]),n("Richtig – Fertig")]),e("p",null,[e("strong",null,"Starten Sie SchILD-NRW neu"),n(", damit die Kataloge und damit die Kurse einmal komplett neu eingelesen werden.")]),e("p",null,"Der Kurs kann im Anschluss bei Schülern in die Leistungsdaten aufgenommen werden.")],-1),r('<h2 id="den-projektkurs-verwenden" tabindex="-1">Den Projektkurs verwenden <a class="header-anchor" href="#den-projektkurs-verwenden" aria-label="Permalink to &quot;Den Projektkurs verwenden&quot;">​</a></h2><h3 id="kurs-bei-schuler-hinzufugen" tabindex="-1">Kurs bei Schüler hinzufügen <a class="header-anchor" href="#kurs-bei-schuler-hinzufugen" aria-label="Permalink to &quot;Kurs bei Schüler hinzufügen&quot;">​</a></h3><p><a href="/bilder/schueler/tutorials-projektkurse-schueler-kurs.png"><img src="'+d+'" alt="Fügen Sie den Kurs wie gewohnt unter Schüler ➜ Akt. Halbjahr ➜ Leistungsdaten dem Schüler zu." loading="lazy"></a></p><p><em>Fügen Sie den Kurs wie gewohnt unter Schüler ➜ Akt. Halbjahr ➜ Leistungsdaten dem Schüler zu.</em></p><p>Der Kurs wird individuell wie gewohnt unter <em>Schüler ➜ Akt. Halbjahr ➜ Leistungsdaten</em> aufgenommen.</p><p>Verfahren Sie bei Gruppen oder dem Halbjahreswechsel wie mit anderen Kursen auch, zum Beispiel durch Zuordnen per Gruppenprozesse, über die Fortschreibungsart beim Abschnittswechsel oder durch einen Import aus einem externen Blockungs- und Kursplanungsprogramm.</p><p>Achten Sie darauf, den Kurs in beiden Halbjahren der Q1 zuzuordnen.</p><h3 id="thema-der-projektkursarbeit-erfassen" tabindex="-1">Thema der Projektkursarbeit erfassen <a class="header-anchor" href="#thema-der-projektkursarbeit-erfassen" aria-label="Permalink to &quot;Thema der Projektkursarbeit erfassen&quot;">​</a></h3><p><a href="/bilder/schueler/tutorials-projektkurse-schueler-thema.png"><img src="'+c+'" alt="Tragen Sie das Theme das Projektkurses unter der Fachbez. Leistungsentw. ein." loading="lazy"></a></p><p><em>Tragen Sie das Theme das Projektkurses unter der <strong>Fachbez. Leistungsentw.</strong> ein.</em></p><p>Das Projektkursthema wird unter <strong>Fachbez. Leistungsentw.</strong> erfasst. Führen Sie einen <code>Doppelklick</code> auf das Feld aus.</p><p>Im folgenden Fenster wird das Thema eingetragen.</p><p>Bestätigen Sie mit einem Klick auf <code>OK</code>.</p><p>Es reicht, das Thema in einem Halbjahr eintragen.</p>',14),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,"Da die Arbeit im zweiten Halbjahr geschrieben wird, bietet es sich an, per Konvention die Arbeiten immer im 2. Halbjahr der Q1 zu erfassen.")],-1),r('<h3 id="im-abitur" tabindex="-1">Im Abitur <a class="header-anchor" href="#im-abitur" aria-label="Permalink to &quot;Im Abitur&quot;">​</a></h3><p><a href="/bilder/sekundarstufen/tutorials-projektkurse-schueler-abitur.png"><img src="'+t+'" alt="Übernehmen Sie das Thema in Schüler ➜ Abitur." loading="lazy"></a></p><p><em>Übernehmen Sie das Thema in Schüler ➜ Abitur.</em></p><p>Im Zuge des Abiturs können Sie das Thema der Projektkursarbeit unter <strong>Projektkurs</strong> frei eintragen.</p><p>Wurde das Thema als <em>Fachbezogene Leistungsentwicklung</em> unter <em>Schüler Akt. Halbjahr Leistungsdaten</em> in der Q1 beim Kurs erfasst, klicken Sie auf <code>Thema ermitteln</code> um es einzulesen.</p>',5),e("div",{"data-hint-kind":"right",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"right","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"m8 12 3 3 5-6"})]),n("Richtig – Fertig")]),e("p",null,"Der Projektkurs wird nun auf dem Abiturzeugnis mit Kursthema und Projektkursarbeit ausgegeben.")],-1),r('<h3 id="note-der-projektkursarbeit-oder-einer-facharbeit-erfassen" tabindex="-1">Note der Projektkursarbeit oder einer Facharbeit erfassen <a class="header-anchor" href="#note-der-projektkursarbeit-oder-einer-facharbeit-erfassen" aria-label="Permalink to &quot;Note der Projektkursarbeit oder einer Facharbeit erfassen&quot;">​</a></h3><p>Noten von Projektkursarbeiten und Facharbeiten lassen sich als <em>Teilleistung</em> bei den Daten des Faches erfassen.</p><p>Legen Sie zuerst eine Teilleistung <em>Projektursarbeit</em> und/oder <em>Facharbeit</em> über <em>Kataloge ➜ Teilleistungsarten</em> an.</p><p>Dann können Sie Teilleistungen über <em>Gruppenprozesse ➜ Teilleistungen</em> ➜ <strong>Teilleistungsarten individuell zuweisen</strong> die Teilleistungen <em>Projektkursarbeit</em> oder <em>Facharbeit</em> der ausgewählten Schülermenge zuweisen.</p><p>Wählen Sie passend <em>Fach</em>, <em>Kursart</em> und die <em>Teilleistung</em>.</p><p>Klicken Sie dann auf <code>Ausführen</code>.</p><p>Im Anschluss kann die Teilleistung über <em>Schüler Akt. Halbjahr Leistungsdaten</em> beim zugeordneten Fach mit der Note in einem Lernabschnitt hinzugefügt werden.</p>',7),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n("Konsultieren Sie bei Bedarf die ausführlicheren Artikel zu "),e("em",null,"Teilleistungen"),n(" in dieser Dokumentation.")])],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Thema_von_Projektkurs_und_Facharbeit_erfassen_(Tutorial)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),n(" · Quellrevision 4850.")],-1)])])}const z=a(g,[["render",k]]);export{w as __pageData,z as default};
